INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.64.0',
  '2026-08-03',
  'Расширение для Firefox подписано Mozilla — ставится постоянно и обновляется само',
  E'Раньше Firefox снимал наше расширение при каждом перезапуске браузера: неподписанные дополнения он ставит только временно. Теперь файл подписан Mozilla, и расширение устанавливается насовсем.\n\nВ Настройках → «Токены доступа» кнопка «Для Firefox» отдаёт готовый файл: откройте его в браузере и подтвердите установку. Распаковывать архив и возиться с about:debugging больше не нужно. Обновления расширение получает само. Для Chrome всё как было — архив и режим разработчика.',
  E'Подпись на addons.mozilla.org в канале unlisted: файл подписан, в каталоге AMO не публикуется, проверка автоматическая. Скрипт internal/extension/sign-firefox.sh собирает staging-каталог (манифест firefox под именем manifest.json, popup.html, иконки, подстановка {{APP_URL}}) и вызывает web-ext sign; ключи API берутся из ~/.config/habits-amo.env и в репозиторий не попадают.\n\nПодпись покрывает байты архива, поэтому собрать .xpi на лету, как zip, нельзя: files/signed/habits-firefox.xpi лежит в репозитории (единственный бинарник) и вшивается go:embed, адрес приложения зашит внутрь в момент подписи. Раздача: GET /ext/habits-firefox.xpi с типом application/x-xpinstall и GET /ext/updates.json (манифест обновлений, на него ссылается update_url в подписанном манифесте) — версия и id для него читаются из самого .xpi, чтобы не разъехались. /ext/habits-firefox.zip оставлен для разработки.\n\nВ манифест firefox добавлен update_url со стандартным плейсхолдером, поэтому подстановка {{APP_URL}} теперь делается и в манифесте, а не только в popup.html. 5 новых тестов: наличие подписи META-INF/mozilla.rsa в .xpi, соответствие id и версии архиву, корректность updates.json и ссылки в нём, отсутствие плейсхолдеров в подписанном файле, подстановка update_url в zip.\n\n⚠️ Эксплуатация: при каждой новой подписи надо поднимать version в manifest.firefox.json — AMO не принимает повторно уже загруженную версию.'
);
-- +goose StatementEnd

